window.PDT_INDEX = [["VCF0004", "Year of Study", "20260205", "variables/20260205/VCF0004.html", "Year of study (4-digit)"], ["VCF0006", "Study Respondent Number: Year-level Case ID", "20260205", "variables/20260205/VCF0006.html", "Case identification number"], ["VCF0009z", "Weight: For 1970 type 0 - 2012-2024 full sample", "20260205", "variables/20260205/VCF0009z.html", "CDF Weight: 1970 type 0 - 2012,2016,2020,2024 full sample"], ["VCF0101", "Respondent - Age", "20260205", "variables/20260205/VCF0101.html", "1964-1976: What is your date of birth? 1978-1982: What is the month and year of your birth? 1984-LATER: What is the month, day and year of your birth?"], ["VCF0104", "Respondent - Gender", "20260205", "variables/20260205/VCF0104.html", "Respondent gender"], ["VCF0201", "Thermometer - Democrats", "20260205", "variables/20260205/VCF0201.html", "Democrats – feeling thermometer"], ["VCF0202", "Thermometer - Republicans", "20260205", "variables/20260205/VCF0202.html", "Republicans – feeling thermometer"], ["VCF0206", "Thermometer - Blacks", "20260205", "variables/20260205/VCF0206.html", "Blacks – feeling thermometer"], ["VCF0207", "Thermometer - Whites", "20260205", "variables/20260205/VCF0207.html", "Whites – feeling thermometer"], ["VCF0211", "Thermometer - Liberals", "20260205", "variables/20260205/VCF0211.html", "Liberals – feeling thermometer"], ["VCF0212", "Thermometer - Conservatives", "20260205", "variables/20260205/VCF0212.html", "Conservatives – feeling thermometer"], ["VCF0218", "Thermometer - Democratic Party", "20260205", "variables/20260205/VCF0218.html", "The Democratic Party – feeling thermometer"], ["VCF0224", "Thermometer - Republican Party", "20260205", "variables/20260205/VCF0224.html", "The Republican Party – feeling thermometer"], ["VCF0230", "Thermometer - Anti-Abortionists", "20260205", "variables/20260205/VCF0230.html", "1984: Anti-abortionists – thermometer 1988,1990: Opponents of abortion – thermometer"], ["VCF0232", "Thermometer - Gays and Lesbians", "20260205", "variables/20260205/VCF0232.html", "Gay men and lesbians (that is), homosexuals – thermometer"], ["VCF0803", "Liberal-Conservative Scale", "20260205", "variables/20260205/VCF0803.html", "We hear a lot of talk these days about liberals and conservatives. Here is (1972,1974: I’m going to show you) a 7-point scale on which the political views that people might hold are arranged from extremely liberal to extremely conservative. Where would you place yourself on this scale, or haven’t you thought much about this? (7-POINT SCALE SHOWN TO R) When it comes to politics, do you usually thin"], ["VCF0301", "Party Identification of Respondent- 7-point Scale", "20260205", "variables/20260205/VCF0301.html", "Generally speaking, do you usually think of yourself as a Republican, a Democrat, an Independent, or what? (IF REPUBLICAN OR DEMOCRAT) Would you call yourself a strong (REP/DEM) or a not very strong (REP/DEM)? (IF INDEPENDENT, OTHER [1966 AND LATER:] OR NO PREFERENCE; 2008: OR DK) Do you think of yourself as closer to the Republican or Democratic party?"], ["VCF0830", "Aid to Blacks Scale", "20260205", "variables/20260205/VCF0830.html", "Some people feel that the government in Washington should make every possible effort to improve the social and economic position of blacks (1970: Negroes) and other minority groups (1980: even if it means giving them preferential treatment). Others feel that the government should not make any special effort to help minorities because they should help themselves (1970: but they should be expected t"], ["VCF0806", "Government Health Insurance Scale", "20260205", "variables/20260205/VCF0806.html", "There is much concern about the rapid rise in medical and hospital costs. Some (1988,1994-LATER: people) feel there should be a government insurance plan which would cover all medical and hospital expenses (1984 AND LATER: for everyone). (1996,2004: Suppose these people are at one end of a scale, at point 1). Others feel that (1988,1994-1996: all) medical expenses should be paid by individuals, an"], ["VCF0837", "When Should Abortion Be Allowed", "20260205", "variables/20260205/VCF0837.html", "(1972,1976: Still on the subject of women’s rights,) There has been some discussion about abortion during recent years. Which one of the opinions on this page (1972: card) best agrees with your view? You can just tell me the number of the opinion you choose."], ["VCF0838", "By Law, When Should Abortion Be Allowed", "20260205", "variables/20260205/VCF0838.html", "There has been some discussion about abortion during recent years. (RESPONDENT BOOKLET) Which one of the opinions on this page best agrees with your view? You can just tell me the number of the opinion you choose. I am going to read you a short list of opinions. Please tell me which one of the opinions best agrees with your view. You can just tell me the number of the opinion you choose."], ["VCF0876", "Law to Protect Homosexuals Against Discrimination", "20260205", "variables/20260205/VCF0876.html", "Do you favor or oppose laws to protect [homosexuals/gays and lesbians] against job discrimination?"], ["VCF0876a", "Strength of Position on Law to Protect Homosexuals Against Discrimination", "20260205", "variables/20260205/VCF0876a.html", "Do you favor or oppose laws to protect [homosexuals/gays and lesbians] against job discrimination? Do you favor/oppose such laws strongly or not strongly?"], ["VCF0877", "Favor or Oppose Gays in the Military", "20260205", "variables/20260205/VCF0877.html", "Do you think homosexuals should be allowed to serve in the United States Armed Forces or don’t you think so?"], ["VCF0877a", "Strength of Position on Gays in the Military", "20260205", "variables/20260205/VCF0877a.html", "Do you feel strongly or not strongly that homosexuals should be allowed to serve in the United States Armed forces? Do you feel strongly or not strongly that homosexuals should not be allowed to serve in the United States Armed forces?"], ["VCF0878", "Should Gays/Lesbians Be Able to Adopt Children", "20260205", "variables/20260205/VCF0878.html", "Do you think gay or lesbian couples, in other words, homosexual couples, should be legally permitted to adopt children?"], ["VCF9236", "Does R favor or oppose the death penalty for persons convicted of murder", "20260205", "variables/20260205/VCF9236.html", "Do you favor or oppose the death penalty for persons convicted of murder?"], ["VCF9237", "R strongly or not strongly favor/oppose the death penalty for persons convicted ", "20260205", "variables/20260205/VCF9237.html", "(Do you favor or oppose the death penalty for persons convicted of murder?) Do you favor the death penalty for persons convicted of murder strongly or not strongly? / Do you oppose the death penalty for persons convicted of murder strongly or not strongly?"], ["VCF0702", "Did Respondent Vote in the National Elections", "20260205", "variables/20260205/VCF0702.html", "In the election, about half the people voted and about half of them didn’t. Did you vote? One of the things we need to know is whether or not people really did get to vote this fall. In talking to people about the election we find that a lot of people weren’t able to vote because they weren’t registered or they were sick or something else came up at the last minute. Do you remember for sure whethe"], ["VCF0704", "Vote for President- Major Candidates", "20260205", "variables/20260205/VCF0704.html", "(IF R VOTED:) Whom did you vote for? (IF R VOTED:) Who did you vote for President? (IF R VOTED:) Who did you vote for in the election for President? (IF R VOTED:) How about the election for President? Did you vote for a candidate for President? (IF YES:) Who did you vote for?"], ["VCF0704a", "Vote for President- Major Parties", "20260205", "variables/20260205/VCF0704a.html", "Major party presidential vote (2 party)"], ["VCF0713", "Respondent Pre-election Intent for Vote for President", "20260205", "variables/20260205/VCF0713.html", "So far as you know now, do you expect to vote in the national elections this coming November or not? (IF YES:) Who do you think you will vote for in the election for President? On the coming Presidential election, do you plan to vote? (IF RESPONSE NOT ‘NO’:) Do you plan to vote Republican, Democrat or something else? We all know the election is some time away and people are not certain at this poi"], ["VCF0128", "Respondent - Religion Major Group", "20260205", "variables/20260205/VCF0128.html", "1952-1964: Is your Church (1962: religious) preference Protestant, Catholic or Jewish? 1966-1968: Are you Protestant, Catholic or Jewish? 1970-1988,2002: Is your religious preference Protestant, Catholic, Jewish, or something else? 1990 AND LATER, exc. 2002: (IF R ATTENDS RELIGIOUS SERVICES:) Do you mostly attend a place of worship that is Protestant, Roman Catholic, Jewish or what? (IF R DOESN’T "], ["VCF0130", "Respondent - Church Attendance 1970-", "20260205", "variables/20260205/VCF0130.html", "1970-1988: (IF ANY RELIGIOUS PREFERENCE) Would you say you/do you go to (church/synagogue) every week, almost every week, once or twice a month, a few times a year, or never? 1990 AND LATER: Lots of things come up that keep people from attending religious services even if they want to. Thinking about your life these days, do you ever attend religious services, apart from occasional weddings, bapti"], ["VCF0846", "Is Religion Important to Respondent", "20260205", "variables/20260205/VCF0846.html", "(2002: Now on another topic. . .) Do you consider religion to be an important part of your life, or not?"], ["VCF0847", "How Much Guidance from Religion", "20260205", "variables/20260205/VCF0847.html", "(IF RELIGION IS IMPORTANT: ) Would you say that (1996-LATER: Would you say your) religion provides some guidance in your day-to-day living, quite a bit of guidance, or a great deal of guidance in your day-to- day living (1996-LATER: ‘life’)?"], ["VCF0850", "Authority of the Bible 1984-", "20260205", "variables/20260205/VCF0850.html", "I am going to read you a short list of statements. Please tell me) Which of these statements comes closest to describing your feelings about the Bible? You can just give me the number of the statement you choose. Please look at page [page] of the booklet. Which of these statements comes closest to describing your feelings about the Bible? You can just give me the number of your choice. (STATEMENTS"]];
